#!/usr/bin/env python3
"""コンテナ / Compose プロジェクトを一覧する Script Filter。"""
import json, os, subprocess, sys

DOCKER = "/usr/local/bin/docker"
query = (sys.argv[1] if len(sys.argv) > 1 else "").strip().lower()

wf_data = os.getenv("alfred_workflow_data") or os.getcwd()
os.makedirs(wf_data, exist_ok=True)
cache_path = os.path.join(wf_data, "projects.json")


def run(args, timeout=5):
    return subprocess.check_output([DOCKER] + args, text=True, timeout=timeout, stderr=subprocess.DEVNULL)


def load_cache():
    try:
        with open(cache_path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def save_cache(cache):
    try:
        with open(cache_path, "w", encoding="utf-8") as f:
            json.dump(cache, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


# --- Docker が使えるか確認 ---
try:
    run(["version", "--format", "{{.Server.Version}}"], timeout=3)
except Exception:
    print(json.dumps({"items": [{
        "title": "Docker / OrbStack が起動していません",
        "subtitle": "OrbStack を起動してから再度お試しください",
        "valid": False,
    }]}, ensure_ascii=False))
    raise SystemExit

items = []

# --- Compose プロジェクト ---
projects = []
try:
    projects = json.loads(run(["compose", "ls", "-a", "--format", "json"]) or "[]")
except Exception:
    projects = []

cache = load_cache()
seen = set()
for p in projects:
    name = p.get("Name", "")
    if not name:
        continue
    seen.add(name)
    config_files = p.get("ConfigFiles", "")
    if config_files:
        cache[name] = config_files
    items.append({
        "kind": "compose",
        "target": name,
        "status": p.get("Status", ""),
        "config_files": config_files,
        "title": f"📦 {name}",
        "subtitle": f"Compose · {p.get('Status', '')}",
        "match": name,
    })

# down 済みで compose ls から消えたプロジェクトもキャッシュから復元する
# （compose ファイルが消えているものは除外し、キャッシュからも落とす）
for name in list(cache):
    if name in seen:
        continue
    config_files = cache[name]
    if not all(os.path.exists(f) for f in config_files.split(",") if f):
        del cache[name]
        continue
    items.append({
        "kind": "compose",
        "target": name,
        "status": "",
        "config_files": config_files,
        "title": f"📦 {name}",
        "subtitle": "Compose · 未作成（down 済み）",
        "match": name,
    })

save_cache(cache)

# --- コンテナ ---
try:
    lines = run(["ps", "-a", "--format", "{{json .}}"]).strip().splitlines()
except Exception:
    lines = []

for line in lines:
    try:
        c = json.loads(line)
    except Exception:
        continue
    name = c.get("Names", "")
    status = c.get("Status", "")
    running = status.startswith("Up")
    items.append({
        "kind": "container",
        "target": name,
        "status": status,
        "config_files": "",
        "title": f"{'🟢' if running else '⚪️'} {name}",
        "subtitle": f"{c.get('Image', '')} · {status}",
        "match": f"{name} {c.get('Image', '')}",
    })

out = []
for it in items:
    if query and query not in it["match"].lower():
        continue
    out.append({
        "title": it["title"],
        "subtitle": it["subtitle"],
        "arg": it["target"],
        "variables": {
            "kind": it["kind"],
            "target": it["target"],
            "status": it["status"],
            "config_files": it["config_files"],
        },
    })

if not out:
    out = [{"title": "該当なし", "subtitle": query, "valid": False}]

print(json.dumps({"items": out}, ensure_ascii=False))

#!/usr/bin/env python3
"""選択した対象に対して実行できるアクションを出す Script Filter。"""
import json, os

kind = os.getenv("kind", "")
target = os.getenv("target", "")
status = os.getenv("status", "")
config_files = os.getenv("config_files", "")

if not target:
    print(json.dumps({"items": [{"title": "対象が取得できません", "valid": False}]}, ensure_ascii=False))
    raise SystemExit


def item(title, action, subtitle=""):
    return {
        "title": title,
        "subtitle": subtitle or target,
        "arg": action,
        "variables": {
            "kind": kind,
            "target": target,
            "action": action,
            "config_files": config_files,
        },
    }


items = []

if kind == "compose":
    # compose ls は "exited(1), running(2)" のように混在状態を返す
    running = "running" in status
    if running:
        items.append(item("restart — 再起動", "restart"))
        items.append(item("stop — 停止", "stop"))
        items.append(item("down — 停止してコンテナ削除", "down"))
    else:
        items.append(item("up — 起動（-d）", "up"))
        if status:
            items.append(item("down — コンテナ削除", "down"))
else:
    running = status.startswith("Up")
    if running:
        items.append(item("shell — コンテナ内に入る", "shell", "tmux セッション containers に新しいタブを作成"))
        items.append(item("restart — 再起動", "restart"))
        items.append(item("stop — 停止", "stop"))
    else:
        items.append(item("start — 起動", "start"))

print(json.dumps({"items": items}, ensure_ascii=False))
